":true,"w":"Baú de Ouro"},{"n":"Platemail de Aquiles","c":"Veste","l":35,"s":"Detectar segredo","r":"Lendário","o":true,"w":"Gear of Legends Pack"},{"n":"Revestimento de Couro Pirata","c":"Veste","l":37,"s":"Catador 2","r":"Lendário","o":true,"w":"A Pirate''s Life Pack"},{"n":"Shadow Lurker","c":"Veste","l":38,"s":"Gangster 1","r":"Lendário","o":true,"w":"Baú Mágico"},{"n":"Valkyrie''s Embrace","c":"Veste","l":40,"s":"Velocista 2","r":"Épico","o":false,"w":"Ninja Pack"},{"n":"Pele de Dragão","c":"Veste","l":41,"s":"Amazona 1","r":"Lendário","o":true,"w":"Baú Mágico"},{"n":"Vampire Hunter","c":"Veste","l":44,"s":"Energético 2","r":"Lendário","o":true,"w":"Monster Hunter''s Toolkit Pack"},{"n":"Cow Hide Vest","c":"Veste","l":45,"s":"Companheiro de Guerra 3","r":"Mítico","o":false,"w":"Wild West Pack"},{"n":"Couro do Oceano","c":"Veste","l":47,"s":"Sábio 3","r":"Épico","o":true,"w":"Baú de Anão"},{"n":"Colete Místico","c":"Veste","l":49,"s":"Encontrar mágica","r":"Mítico","o":true,"w":"Heroic Pack #2"},{"n":"Esmeralda Marcha","c":"Veste","l":50,"s":"Detectar segredo","r":"Impecável","o":true,"w":"Force of Nature Pack"},{"n":"Corvo Negro","c":"Veste","l":50,"s":"Passo das Sombras","r":"Mítico","o":true,"w":"Baú Primordial"},{"n":"Couraça Real","c":"Veste","l":55,"s":"Engenhoso 3","r":"Mítico","o":true,"w":"Baú Primordial"},{"n":"Invincible Scales","c":"Veste","l":56,"s":"Energético 3","r":"Mítico","o":true,"w":"Flaming Rain Pack"}]';
BEGIN
    FOR entry IN SELECT * FROM jsonb_array_elements(items_json)
    LOOP
        CASE entry->>'c'
            WHEN 'Arco', 'Cajado', 'Faca', 'Espada', 'Lança', 'Machado', 'Martelo', 'Pistola' THEN v_slot := 'Arma';
            WHEN 'Túnica', 'Veste', 'Armadura' THEN v_slot := 'Peito';
            WHEN 'Chapéu', 'Elmo' THEN v_slot := 'Cabeça';
            WHEN 'Luvas', 'Manopla' THEN v_slot := 'Mãos';
            WHEN 'Sapatos', 'Botas' THEN v_slot := 'Pés';
            ELSE v_slot := 'Acessório';
        END CASE;

        SELECT id INTO it_id FROM item_types WHERE name = (entry->>'c');
        -- If skill not found, it will be NULL
        SELECT id INTO sk_id FROM skills WHERE name = (entry->>'s');

        INSERT INTO public.items (name, item_type_id, slot_type, level, skill_id, rarity, is_owned, where_to_get)
        VALUES (
            entry->>'n', 
            it_id, 
            v_slot, 
            (entry->>'l')::INTEGER, 
            sk_id, 
            entry->>'r', 
            (entry->>'o')::BOOLEAN,
            entry->>'w'
        ) ON CONFLICT (name) DO UPDATE SET 
            where_to_get = EXCLUDED.where_to_get,
            is_owned = EXCLUDED.is_owned,
            item_type_id = EXCLUDED.item_type_id,
            slot_type = EXCLUDED.slot_type,
            level = EXCLUDED.level,
            skill_id = EXCLUDED.skill_id,
            rarity = EXCLUDED.rarity;
    END LOOP;
END $SEED$;
